import * as T from './vendor/three.js';
import {createTrafficRules} from './traffic-rules.js?v=traffic-cpu-1';
import {overlapsVehicle} from './vehicle-contact.js?v=cockpit-breakaway-53';
import {stepCar} from './vehicle-physics.js?v=handbrake-76';
import {createHeadlightPools} from './night-lights.js?v=night-walls-73';
import {CLASSICS,createClassicFleet} from './classic-cars.js?v=release-1';
export function createTraffic(scene,network,count=144,{parkingClear=()=>true,physicsWorld=null,viewDirection=null}={}){
 const nodes=new Map(),edges=[];const id=p=>p.node||p.x.toFixed(2)+','+p.y.toFixed(2);
 for(const r of network.roads){if(!['residential','unclassified','tertiary','secondary','primary','living_street'].includes(r.type)||r.tags.access==='private'||r.tags.motor_vehicle==='no')continue;for(let i=0;i<r.p.length-1;i++){const a=r.p[i],b=r.p[i+1],length=a.distanceTo(b);if(length<1)continue;const add=reverse=>{const from=reverse?b:a,to=reverse?a:b,e={r,i,reverse,from,to,length,fromId:id(from),toId:id(to)};edges.push(e);if(!nodes.has(e.fromId))nodes.set(e.fromId,[]);nodes.get(e.fromId).push(e)};if(r.tags.oneway!=='-1')add(false);if(r.tags.oneway!=='yes'&&r.tags.junction!=='roundabout')add(true)}}
 let seed=519;const random=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const queenEdges=edges.filter(e=>e.r.name==='Queen Street'&&e.length>12);const initial=edges.filter(e=>Math.hypot(e.from.x,e.from.y)<900&&e.length>12),others=edges.filter(e=>e.length>15);const cars=Array.from({length:Math.min(count+10,edges.length)},(_,i)=>{let pool=(i<12||i>=count)&&queenEdges.length?queenEdges:i<48&&initial.length?initial:others;const model=CLASSICS[i%CLASSICS.length];if(model.bus){const wide=others.filter(e=>e.r.width>=7&&e.length>model.length*1.5);if(wide.length)pool=wide}const edge=i===0&&queenEdges.length?queenEdges[0]:pool[Math.floor(random()*pool.length)];return{edge,distance:edge.length*(.1+random()*.8),parked:i>=count,speed:i>=count?0:6+random()*5,velocity:0,yaw:0,position:null,index:i}});
 function routePose(car){const base=position(car);if(car.parked)return base;let a,b,t;if(car.previousEdge){const radius=Math.min(8,car.previousEdge.length*.45,car.edge.length*.45);if(car.distance<radius){a=car.previousEdge;b=car.edge;t=.5+car.distance/(radius*2)}}if(!a&&car.routePlan?.[0]){const radius=Math.min(8,car.edge.length*.45,car.routePlan[0].length*.45);if(car.edge.length-car.distance<radius){a=car.edge;b=car.routePlan[0];t=.5-(car.edge.length-car.distance)/(radius*2)}}if(!a)return base;const radius=Math.min(8,a.length*.45,b.length*.45),p=position({edge:a,distance:a.length-radius}),q=position({edge:b,distance:radius}),cross=p.dx*q.dz-p.dz*q.dx;let cx=(p.x+q.x)/2,cz=(p.z+q.z)/2;if(Math.abs(cross)>.05){const u=((q.x-p.x)*q.dz-(q.z-p.z)*q.dx)/cross;cx=p.x+p.dx*u;cz=p.z+p.dz*u}else if(p.dx*q.dx+p.dz*q.dz<0){cx=a.to.x;cz=a.to.y}const u=1-t,dx=2*u*(cx-p.x)+2*t*(q.x-cx),dz=2*u*(cz-p.z)+2*t*(q.z-cz),length=Math.hypot(dx,dz)||1;return{x:u*u*p.x+2*u*t*cx+t*t*q.x,z:u*u*p.z+2*u*t*cz+t*t*q.z,y:p.y*(1-t)+q.y*t,dx:dx/length,dz:dz/length}}
 const rules=createTrafficRules(network,edges,nodes,random,{railCrossings:()=>physicsWorld?.railways?.levelCrossings||[]});
 const fleet=createClassicFleet(scene,cars,{maxDistance:1500,visible:(car,p)=>physicsWorld?.visibility?physicsWorld.visibility.instance(car,p.x,p.y,p.z,car.model.length/2+.3,(car.model.roof||2)+.3):true}),headlights=createHeadlightPools(scene,cars.length);
 function position(car){const e=car.edge,t=Math.min(1,car.distance/e.length),dx=(e.to.x-e.from.x)/e.length,dz=(e.to.y-e.from.y)/e.length,lane=car.parked?e.r.width/2+.6:Math.min(e.r.width*.23,2.5),x=T.MathUtils.lerp(e.from.x,e.to.x,t)+dz*lane,z=T.MathUtils.lerp(e.from.y,e.to.y,t)-dx*lane,rt=e.reverse?1-t:t,y=network.height(e.r,e.i,rt,x,z);return{x,z,y,dx,dz}}
 for(const car of cars.filter(c=>c.parked)){for(let attempt=0;attempt<14;attempt++){if(parkingClear(position(car),car.model))break;car.distance=(car.distance+6)%car.edge.length;if(attempt===13){car.parked=false;car.speed=6}}}
 // Snapshot spatial buckets replace the old all-pairs following scan.
 const buckets=new Map(),cellSize=32;let clock=0,nextRefill=0,recycled=0,localCount=0,density=1;
 function rebuildBuckets(){buckets.clear();for(const car of cars){const p=car.renderPosition||car.position;if(!p)continue;const key=Math.floor(p.x/cellSize)+','+Math.floor(p.z/cellSize);if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(car)}}
 function neighbours(p){const found=[];for(let x=-1;x<=1;x++)for(let z=-1;z<=1;z++)found.push(...(buckets.get((Math.floor(p.x/cellSize)+x)+','+(Math.floor(p.z/cellSize)+z))||[]));return found}
 function place(car,pool,camera,minDistance,maxDistance,direction){const oldEdge=car.edge,oldDistance=car.distance;for(let attempt=0;attempt<80&&pool.length;attempt++){const e=pool[Math.floor(random()*pool.length)];if(car.model.bus&&(e.r.width<7||e.length<car.model.length*1.5))continue;car.edge=e;car.distance=e.length*(.08+random()*.84);const p=position(car),dx=p.x-camera.x,dz=p.z-camera.z,d=Math.hypot(dx,dz);if(d<minDistance||d>maxDistance||direction&&(dx*direction.x+dz*direction.z)>-.15*d)continue;
  if(rules.nearJunction(p,car.model.length/2+2))continue;
  if(physicsWorld?.freeSpace&&!physicsWorld.freeSpace(p.x,p.z,p.y+2))continue;
  if(cars.some(other=>{if(other===car||!other.position||Math.abs(other.position.y-p.y)>3)return false;const x=other.position.x-p.x,z=other.position.z-p.z;return Math.abs(x*p.dx+z*p.dz)<(car.model.length+other.model.length)/2+4&&Math.abs(x*p.dz-z*p.dx)<(car.model.width+other.model.width)/2+.35}))continue;
  car.position={...p};car.yaw=Math.atan2(-p.dx,-p.dz);car.velocity=0;delete car.bodyPitch;delete car.bodyRoll;car.pitch=undefined;rules.reset(car);return true}car.edge=oldEdge;car.distance=oldDistance;return false}
 // Seed poses before checking spacing; each car is then placed against its neighbours.
 for(const car of cars){const p=position(car);car.position={...p};car.yaw=Math.atan2(-p.dx,-p.dz)}
 for(const car of cars.filter(c=>!c.parked))place(car,car.index<12&&queenEdges.length?queenEdges:Math.hypot(car.position.x,car.position.z)<950&&initial.length?initial:others,{x:0,z:0},0,Infinity,null);
 // density (setDensity, from the graphics tier) scales how many moving cars are kept near the camera. Over the cap, surplus
 // cars behind the camera are sent past simulation range (1.7 km), a few a second, rather than vanishing in view.
 function refill(camera){const moving=cars.filter(c=>!c.parked&&!c.controlled&&!c.manualPark);localCount=moving.filter(c=>Math.hypot(c.position.x-camera.x,c.position.z-camera.z)<850).length;let close=moving.filter(c=>Math.hypot(c.position.x-camera.x,c.position.z-camera.z)<350).length;const cap=Math.round(64*density),busy=Math.round(48*density),closeCap=Math.round(12*density);
  if(localCount>cap){const direction=viewDirection?.();let sent=0;for(const car of moving){if(localCount<=cap||sent>=8)break;if(car.model.bus)continue;const dx=car.position.x-camera.x,dz=car.position.z-camera.z,d=Math.hypot(dx,dz);if(d>=850||d<60||(direction?dx*direction.x+dz*direction.z>-.15*d:d<500))continue;if(place(car,others,camera,1800,Infinity,null)){localCount--;sent++}}return}
  if(localCount>=cap||localCount>=busy&&close>=closeCap)return;const pool=others.filter(e=>{const x=(e.from.x+e.to.x)/2,z=(e.from.y+e.to.y)/2;return Math.hypot(x-camera.x,z-camera.z)<1000+e.length/2}),direction=viewDirection?.();let added=0;
  for(const car of moving){if(localCount>=cap||localCount>=busy&&close>=closeCap||added>=8)break;if(Math.hypot(car.position.x-camera.x,car.position.z-camera.z)<1700)continue;if(place(car,pool,camera,180,close<closeCap?340:800,direction)){localCount++;if(Math.hypot(car.position.x-camera.x,car.position.z-camera.z)<350)close++;added++;recycled++}}
 }
 // Body pitch follows the ground under both axles. Beyond 300 m the tilt is too small to see, so far cars keep
 // their last pitch instead of sampling the ground twice a frame.
 function renderCar(car,p,dt,far=false){const wheelbase=car.model.wheelbase,heading=car.renderYaw??car.yaw,dx=-Math.sin(heading),dz=-Math.cos(heading),pose=car.renderPosition||car.position,x=pose.x,z=pose.z;let target;if(car.inWater)target=car.waterPitch||0;else if(car.bodyPitch!=null)target=car.bodyPitch;else if(far&&car.pitch!==undefined)target=car.pitch;else{const front=network.walkHeight(x+dx*wheelbase/2,z+dz*wheelbase/2,pose.y+2),rear=network.walkHeight(x-dx*wheelbase/2,z-dz*wheelbase/2,pose.y+2);target=Math.atan2(front-rear,wheelbase)}car.pitch=car.pitch===undefined?target:T.MathUtils.lerp(car.pitch,target,1-Math.exp(-dt*8));fleet.write(car,car.pitch)}
 function update(dt,camera,night=0){clock+=dt;if(dt>0&&clock>=nextRefill){nextRefill=clock+1;refill(camera)}rebuildBuckets();rules.prepare(cars,dt,physicsWorld?.people?.people||[],camera);for(const car of cars){if(car.controlled||car.manualPark){if(!car.controlled&&physicsWorld&&(car.inWater||car.airborne))stepCar(car,{},Math.min(dt,.05),physicsWorld);renderCar(car,car.position,dt);continue}const range=car.position?Math.hypot(car.position.x-camera.x,car.position.z-camera.z):0;if(range>1700)continue;const current=routePose(car);let target=car.speed;const px=camera.x-current.x,pz=camera.z-current.z,forward=px*current.dx+pz*current.dz;if(forward>0&&forward<9+car.model.length/2&&Math.abs(px*current.dz-pz*current.dx)<2.2&&Math.abs(camera.y-current.y)<4)target=car.speed*Math.max(0,(forward-2-car.model.length/2)/6);for(const other of neighbours(current)){if(other===car||!other.position||Math.abs(other.position.y-current.y)>3)continue;let dx=other.position.x-current.x,dz=other.position.z-current.z,d=dx*current.dx+dz*current.dz;if(d>0&&d<7+(car.model.length+other.model.length)/2&&Math.abs(dx*current.dz-dz*current.dx)<1.6)target=Math.min(target,car.speed*Math.max(0,(d-1-(car.model.length+other.model.length)/2)/6))}const rule=rules.speedLimit(car);target=Math.min(target,rule.limit);if(car.collisionWait>0){car.collisionWait=Math.max(0,car.collisionWait-dt);target=0}car.braking=target<Math.abs(car.velocity)-.6||target<.2;car.velocity+=T.MathUtils.clamp(target-car.velocity,-4.5*dt,(car.model.bus?1.5:car.model.van?2.3:3.5)*dt);const oldDistance=car.distance,oldEdge=car.edge,oldPrevious=car.previousEdge,oldPlan=car.distance+car.velocity*dt>=car.edge.length?car.routePlan.slice():null;car.distance+=Math.min(car.velocity*dt,rule.stopDistance);if(rule.stopDistance<.02&&!car.trafficAllowed)car.velocity=0;let safety=0;while(car.distance>=car.edge.length&&safety++<8){car.distance-=car.edge.length;const previous=car.edge,next=rules.next(car);if(!next){car.distance=previous.length-.02;car.velocity=0;break}car.turnIndicator=car.indicator;car.previousEdge=previous;car.edge=next;car.routeHead=next;}const p=routePose(car);if(neighbours(p).some(other=>other!==car&&overlapsVehicle(car,p,other))){car.distance=oldDistance;car.edge=oldEdge;car.previousEdge=oldPrevious;car.routeHead=oldEdge;if(oldPlan)car.routePlan=oldPlan;car.velocity=0;car.braking=true;p.x=car.position.x;p.z=car.position.z;p.y=car.position.y}const targetYaw=Math.atan2(-p.dx,-p.dz);if(!car.position){car.position={...p};car.yaw=targetYaw}else{car.position.x=T.MathUtils.lerp(car.position.x,p.x,1-Math.exp(-dt*9));car.position.z=T.MathUtils.lerp(car.position.z,p.z,1-Math.exp(-dt*9));car.position.y=p.y;const angle=Math.atan2(Math.sin(targetYaw-car.yaw),Math.cos(targetYaw-car.yaw));car.yaw+=angle*(1-Math.exp(-dt*7))}renderCar(car,p,dt,range>300)}fleet.finish(night,camera,clock);headlights.update(cars,night,camera)}
 if(physicsWorld)physicsWorld.vehicleContact=(car,p)=>{for(const other of neighbours(p))if(other!==car&&overlapsVehicle(car,p,other))return other;for(const person of physicsWorld.people?.people||[]){const q=person.position;if(Math.abs(q.y-p.y)>2)continue;const x=q.x-p.x,z=q.z-p.z;if(Math.abs(x*Math.sin(car.yaw)+z*Math.cos(car.yaw))<(car.model.length/2+.35)&&Math.abs(x*Math.cos(car.yaw)-z*Math.sin(car.yaw))<car.model.width/2+.3){physicsWorld.people?.avoidVehicle?.(person,car);return{human:true,velocity:0}}}return null};
 update(0,new T.Vector3(0,1000,0));return{cars,edges,nodes,rules,update,setDensity(k){density=k;nextRefill=0},get stats(){return{moving:cars.filter(c=>!c.parked&&!c.manualPark).length,nearby:localCount,recycled,...rules.stats}}};
}
